// ═══════════════════════════════════════════════════════════════
// IDENTIFICA PLATAFORMA
// FIX: os encurtadores do Mercado Livre (meli.la / mlb.la) NAO contem
// a string "mercadolivre.com", entao caiam em "outra" e o Switch
// descartava o item em silencio -> o webhook nunca respondia e o
// front caia no texto generico ("Produto Especial").
// ═══════════════════════════════════════════════════════════════

// Fonte do link: prioriza a URL ja desencurtada; se o :3052 falhou
// (onError=continueRegularOutput deixa passar {error:...}), usa o link cru.
let link = '';
try { link = $('DESENCURTADOR_DE_LINK5').first().json.url_final || ''; } catch (e) {}
if (!link) {
  try { link = $('Webhook').first().json.body.link_produto || ''; } catch (e) {}
}
link = String(link || '').trim();

if (!link) {
  throw new Error('Nenhum link utilizavel (desencurtador e webhook vazios)');
}

const l = link.toLowerCase();

const SHOPEE = ['shopee.com', 's.shopee', 'shp.ee'];
const ML     = ['mercadolivre.com', 'mercadolibre.com', 'meli.la', 'mlb.la'];
const AMAZON = ['amazon.com', 'amzn.to', 'amzn.eu', 'amzn.asia'];

let plataforma = 'outra';
if (SHOPEE.some(function (d) { return l.indexOf(d) !== -1; })) {
  plataforma = 'shopee';
} else if (ML.some(function (d) { return l.indexOf(d) !== -1; })) {
  plataforma = 'mercadolivre';
} else if (AMAZON.some(function (d) { return l.indexOf(d) !== -1; })) {
  plataforma = 'amazon';
}

// Sinaliza link do ML que continua encurtado: o :3060 e o :3099 precisam
// da URL final, entao vale registrar no log quando o desencurtador nao abriu.
const aindaCurto = /meli\.la|mlb\.la|\/sec\//i.test(link);
if (plataforma === 'mercadolivre' && aindaCurto) {
  console.warn('ML: link ainda encurtado apos o :3052 -> ' + link);
}

return { plataforma: plataforma, link_original: link, ainda_curto: aindaCurto };

// FIX: antes o Switch nao tinha saida de fallback. Qualquer plataforma
// nao reconhecida era descartada sem resposta e a requisicao do front
// ficava pendurada ate dar timeout.
let link = '';
try { link = $('IDENTIFICA PLATAFORMA').first().json.link_original || ''; } catch (e) {}

return {
  json: {
    success: false,
    erro: 'Plataforma nao suportada ou link nao desencurtado: ' + link,
    oferta: '',
    imagem: ''
  }
};

const item = $input.first().json;
let link = '';

// 1) Preferido: URL limpa do puppeteer (:3060)
try { const ml = $('puppeter4').first().json; if (ml && ml.url_limpa) link = ml.url_limpa; } catch (e) {}

// FALLBACK (fix 06/08): puppeter4 vai p/ VPS2 e o ML geo-bloqueia IP US -> url_limpa vazio.
try { if (!link) { const dz = $('DESENCURTADOR_DE_LINK5').first().json; if (dz && dz.url_final) link = dz.url_final; } } catch (e) {}

// 3) Ultimo recurso: link cru do webhook
try { if (!link) { const wb = $('Webhook').first().json; if (wb && wb.body && wb.body.link_produto) link = wb.body.link_produto; } } catch (e) {}

// FIX: antes seguia com link vazio e todo o resto da cadeia ML falhava mudo.
if (!link) {
  throw new Error('Mercado Livre: nenhum link utilizavel apos puppeter4 / desencurtador / webhook');
}

return [{ json: { link: link, tom: item.tom || 'normal' } }];

// ═══════════════════════════════════════════════════════════════
// VALIDA PRODUTO ML
// FIX: quando o extrator (:3099) devolvia vazio, o AI Agent recebia
// campos em branco e copiava o template literal ("[Nome do Produto]",
// "[PRECO_ATUAL]"). O guard do Code in JavaScript15 bloqueava e o
// usuario recebia success:false sem nenhuma explicacao.
// Agora a falta de dados e detectada ANTES da IA e vira erro explicito.
// ═══════════════════════════════════════════════════════════════

let p = {};
try { p = $('HTTP Request4').first().json || {}; } catch (e) {}

function num(v) {
  if (v === null || v === undefined || v === '') return null;
  let s = String(v).replace(/[^\d.,-]/g, '');
  // 1.234,56 -> 1234.56   |   1234.56 fica como esta
  if (/,\d{1,2}$/.test(s)) s = s.replace(/\./g, '').replace(',', '.');
  else s = s.replace(/,/g, '');
  const n = parseFloat(s);
  return isFinite(n) ? n : null;
}

function brl(n) {
  if (n === null) return '';
  // 1234.5 -> R$1.234,50 (separador de milhar + virgula decimal)
  const partes = n.toFixed(2).split('.');
  const inteiro = partes[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return 'R$' + inteiro + ',' + partes[1];
}

const titulo        = String(p.titulo || p.title || p.nome || '').trim();
const precoAtual    = num(p.precoAtual !== undefined ? p.precoAtual : (p.preco !== undefined ? p.preco : p.price));
const precoOriginal = num(p.precoOriginal !== undefined ? p.precoOriginal : p.precoDe);
const descricao     = String(p.descricao || p.description || '').trim();

let imagem = String(p.imagem || p.image || '').trim();
if (!imagem) {
  try { imagem = $('Edit Fields6').first().json.imagem || ''; } catch (e) {}
}

let link = '';
try { link = $('Edit Fields6').first().json.link || ''; } catch (e) {}

let tom = 'padrao';
try { tom = $('Webhook').first().json.body.tom || 'padrao'; } catch (e) {}

// Desconto: usa o do extrator, senao calcula a partir dos precos.
let desconto = String(p.desconto || '').trim();
if (!desconto && precoOriginal && precoAtual && precoOriginal > precoAtual) {
  desconto = Math.round((1 - precoAtual / precoOriginal) * 100) + '%';
}

// Sem titulo OU sem preco a oferta nao tem como ser honesta -> nao chama a IA.
const dados_ok = !!(titulo && precoAtual);
if (!dados_ok) {
  console.error('ML: extrator :3099 sem dados uteis para ' + link + ' -> ' + JSON.stringify(p).slice(0, 300));
}

return {
  json: {
    dados_ok: dados_ok,
    titulo: titulo,
    preco_atual: brl(precoAtual),
    preco_original: precoOriginal && precoAtual && precoOriginal > precoAtual ? brl(precoOriginal) : '',
    desconto: desconto,
    descricao: descricao,
    imagem: imagem,
    link: link,
    tom: tom
  }
};

const oferta = $item("0").$node["AI Agent9"].json["output"] || '';

let imagem = '';

// 1) Principal: imagem ja normalizada (extrator :3099 -> og:image)
try {
  const v = $('Valida Produto ML').first().json;
  if (v && v.imagem) imagem = v.imagem;
} catch (e) {}

// 2) Fallback: base64 da og:image (caminho antigo)
if (!imagem) {
  try {
    const b64 = $('Extract File ML2').first().json.data;
    if (b64 && typeof b64 === 'string' && b64.length > 100) {
      imagem = 'data:image/jpeg;base64,' + b64;
    }
  } catch (e) {}
}

// FIX 22/08: guarda anti-template. O prompt usava 'preco original'/'preco atual'
// como placeholder ambiguo e o modelo as vezes copiava o template literal.
function _saneia(txt) {
  var t = String(txt || '');
  var tituloQuebrado = /\[Nome do Produto\]/i.test(t)
    || /^\s*T[íi]tulo\s*:?\s*$/mi.test(t)
    || /^\s*\*{0,2}\s*Produto\s*\*{0,2}\s*$/mi.test(t);
  if (tituloQuebrado) return { ok: false, motivo: 'template nao preenchido (titulo)', texto: t };
  var phPreco = /\[PRECO_ORIGINAL\]|\[PRECO_ATUAL\]|preço original|preço atual|preco original|preco atual/i.test(t);
  var mDe  = t.match(/De\s*~\s*R?\$?\s*([\d.,]+)\s*~/i);
  var mPor = t.match(/\bPor\b[^*]*\*\s*R?\$?\s*([\d.,]+)\s*\*/i);
  var semDesconto = !!(mDe && mPor && mDe[1].trim() === mPor[1].trim());
  if (phPreco || semDesconto) {
    t = t.split('\n').filter(function (l) {
      return !(/De\s*~/i.test(l) || /\bPor\b[^*]*\*/i.test(l));
    }).join('\n').replace(/\n{3,}/g, '\n\n').trim();
  }
  return { ok: true, texto: t, ajustado: (phPreco || semDesconto) };
}

var _g = _saneia(oferta);
if (!_g.ok) {
  console.error('OFERTA BLOQUEADA: ' + _g.motivo);
  return { json: { success: false, erro: _g.motivo, oferta: '', imagem: '' } };
}
if (_g.ajustado) console.warn('linha de preco removida (placeholder ou De=POR)');
return { json: { success: true, oferta: _g.texto, imagem: imagem } };

// Sem titulo/preco o extrator do ML nao entregou nada utilizavel.
// Responde explicitamente em vez de deixar a IA inventar ou o webhook pendurar.
let link = '';
try { link = $('Valida Produto ML').first().json.link || ''; } catch (e) {}

return {
  json: {
    success: false,
    erro: 'Nao foi possivel ler os dados do produto no Mercado Livre (extrator :3099 sem titulo/preco). Link: ' + link,
    oferta: '',
    imagem: ''
  }
};

// ═══════════════════════════════════════════════════════════════
// CREATORS API - BUSCAR TOKEN OAUTH 2.0 (v3.1 LWA)
// ═══════════════════════════════════════════════════════════════

const credentialId = $env.AMAZON_CLIENT_ID;
const credentialSecret = $env.AMAZON_CLIENT_SECRET;

if (!credentialId || !credentialSecret) {
  throw new Error('AMAZON_CLIENT_ID / AMAZON_CLIENT_SECRET nao definidos no ambiente do n8n');
}

const tokenUrl = 'https://api.amazon.com/auth/o2/token';

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: tokenUrl,
  headers: {
    'Content-Type': 'application/x-www-form-urlencoded'
  },
  body: 'grant_type=client_credentials'
    + '&client_id=' + encodeURIComponent(credentialId)
    + '&client_secret=' + encodeURIComponent(credentialSecret)
    + '&scope=creatorsapi::default',
  returnFullResponse: false,
  json: true
});

if (!response.access_token) {
  throw new Error('Falha ao obter token OAuth: ' + JSON.stringify(response));
}

return {
  json: {
    access_token: response.access_token,
    token_type: response.token_type,
    expires_in: response.expires_in
  }
};

// ═══════════════════════════════════════════════════════════════
// CREATORS API - MONTAR REQUEST GetItems (v3.1 LWA)
// ═══════════════════════════════════════════════════════════════
const accessToken = $item("0").$node["Token OAuth Amazon"].json["access_token"];
const partnerTag = 'descontovipon-20';
const urlFinal = $item("0").$node["IDENTIFICA PLATAFORMA"].json["link_original"];

// Extrair ASIN do link da Amazon
const asinMatch = urlFinal.match(/\/dp\/([A-Z0-9]{10})|\/gp\/product\/([A-Z0-9]{10})/);
const asin = asinMatch ? (asinMatch[1] || asinMatch[2]) : null;
if (!asin) {
  throw new Error('ASIN não encontrado no link: ' + urlFinal);
}

// FIX: o marketplace estava gravado como markdown ('[www.amazon.com.br](...)'),
// o que a Creators API rejeita. Tem que ser o host puro.
const MARKETPLACE = 'www.amazon.com.br';

const url = 'https://creatorsapi.amazon/catalog/v1/getItems';
const payload = JSON.stringify({
  itemIds: [asin],
  itemIdType: 'ASIN',
  marketplace: MARKETPLACE,
  partnerTag: partnerTag,
  resources: [
    'itemInfo.title',
    'offersV2.listings.price',
    'images.primary.large'
  ]
});
return {
  json: {
    url: url,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + accessToken,
      'x-marketplace': MARKETPLACE
    },
    body: payload
  }
};

const item = $input.first().json;

let link = '';
let imagem = '';

// AMAZON
try {
  const amz = $('APIAMAZON').first().json;
  if (amz && amz.itemsResult && amz.itemsResult.items && amz.itemsResult.items[0]) {
    const it = amz.itemsResult.items[0];
    if (it.detailPageURL) link = it.detailPageURL;
    if (it.images && it.images.primary && it.images.primary.large && it.images.primary.large.url) {
      imagem = it.images.primary.large.url;
    }
  }
} catch (e) {}

// Fallback de link: URL desencurtada
if (!link) {
  try { const dz = $('IDENTIFICA PLATAFORMA').first().json; if (dz && dz.link_original) link = dz.link_original; } catch (e) {}
}

return {
  json: {
    link: link,
    imagem: imagem,
    tom: item.tom || 'normal'
  }
};

const oferta = $item("0").$node["AI Agent3"].json["output"] || '';
const imagem = $item("0").$node["Edit Fields"].json["imagem"] || '';

// FIX 22/08: guarda anti-template. O prompt usava 'preco original'/'preco atual'
// como placeholder ambiguo e o modelo as vezes copiava o template literal.
