    }).join('\n').replace(/\n{3,}/g, '\n\n').trim();
  }
  return { ok: true, texto: t, ajustado: (phPreco || semDesconto) };
}

var _g = _saneia(oferta);
if (!_g.ok) {
  console.error('OFERTA BLOQUEADA: ' + _g.motivo);
  return { json: { success: false, erro: _g.motivo, oferta: '', imagem: '' } };
}
if (_g.ajustado) console.warn('linha de preco removida (placeholder ou De=POR)');
return { json: { success: true, oferta: _g.texto, imagem: imagem } };

const crypto = require('crypto');

const appId     = $item("0").$node["Buscar Chaves API"].json["shopee_affiliate_id"];
const appSecret = $item("0").$node["Buscar Chaves API"].json["shopee_app_key"];

const url   = $item("0").$node["DESENCURTADOR_DE_LINK"].json["url_final"] || '';
const limpa = url.split('?')[0].split('#')[0];   // tira query/hash p/ não capturar número errado

let shopId = null, itemId = null;

// 1) Formato atual: .../nome-do-produto-i.SHOPID.ITEMID
let m = limpa.match(/i\.(\d+)\.(\d+)/);
if (m) { shopId = m[1]; itemId = m[2]; }

// 2) Formato antigo/app: .../product/SHOPID/ITEMID
if (!shopId) {
  m = limpa.match(/\/product\/(\d+)\/(\d+)/);
  if (m) { shopId = m[1]; itemId = m[2]; }
}

// 3) Fallback: dois blocos numéricos longos
if (!shopId) {
  m = limpa.match(/(\d{6,})[.\/](\d{6,})/);
  if (m) { shopId = m[1]; itemId = m[2]; }
}

// FIX 22/08: distingue BLOQUEIO da Shopee de falha de parsing.
// A /verify/traffic e a pagina anti-bot: nao existe produto nela.
var NAO_E_PRODUTO = [/\/verify\/traffic/i, /is_logged_in=false/i, /shopee\.com\.br\/m\//i,
                     /cupom-de-desconto/i, /voucher-wallet/i, /shopee-coins/i, /\/user\//i];
if (NAO_E_PRODUTO.some(function (re) { return re.test(url); })) {
  throw new Error('Shopee bloqueou a requisicao (anti-bot / pagina nao-produto): ' + limpa.slice(0, 160));
}

// NUNCA seguir com id nulo — sem filtro a Shopee devolve produto aleatório
if (!shopId || !itemId) {
  throw new Error('Shopee: não consegui extrair shopId/itemId de: ' + url);
}

const timestamp = Math.floor(Date.now() / 1000);

const payload = `{"query":"{ productOfferV2(itemId: ${itemId}, shopId: ${shopId}) { nodes { itemId shopId productName offerLink imageUrl commissionRate price priceMin priceMax priceDiscountRate } } }"}`;

const signature = crypto.createHash('sha256')
  .update(appId + timestamp + payload + appSecret)
  .digest('hex');

return [{ json: {
  authHeader: `SHA256 Credential=${appId}, Timestamp=${timestamp},Signature=${signature}`,
  payload, itemId, shopId, timestamp
}}];

const oferta = $item("0").$node["AI Agent"].json["output"] || '';

let imagem = '';
try {
  const n = $('API SHOPEE').first().json.data.productOfferV2.nodes[0];
  imagem = (n && n.imageUrl) || '';
} catch (e) {}

